119	    /** The Luhn check digit over the digits of the owner's customerCode; null until a code is assigned. */
120	    default Integer checkDigit(Owner owner) {
121	        if (owner == null || owner.getCustomerCode() == null) {
122	            return null;
123	        }
124	        return Luhn.checkDigit(owner.getCustomerCode());
125	    }
